namespace FluxLimiter;
internal readonly record struct DayBars(DateTime Day,long Rx,long Tx);
internal sealed record TopApp(string Name,Image? Icon,long Bytes);
internal enum RowAction{Edit,ToggleBlock}
internal sealed class DashboardView:Panel {
 public DataGridView Grid{get;}=new(); public TextBox SearchBox{get;}=new(); public ComboBox FilterBox{get;}=new();
 public event EventHandler? SeeAllClicked; public event Action<int,RowAction>? RowActionClicked; public event Action<int,bool,int?,bool>? LimitChosen;
 readonly Label down=new(),up=new(),daily=new(),monthly=new(),net=new(),footer=new(); readonly FlowLayoutPanel days=new(),tops=new();
 public DashboardView(){Dock=DockStyle.Fill;BackColor=Palette.Bg;Padding=new Padding(24,18,24,18);
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,BackColor=Palette.Bg};root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));root.RowStyles.Add(new RowStyle(SizeType.Absolute,108));root.RowStyles.Add(new RowStyle(SizeType.Absolute,205));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,24));Controls.Add(root);
  var head=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};head.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));head.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,250));var title=new Label{Text="Dashboard\nOverview of your network usage and active applications",Dock=DockStyle.Fill,ForeColor=Color.White,Font=new Font("Segoe UI",19,FontStyle.Bold)};net.TextAlign=ContentAlignment.MiddleCenter;net.ForeColor=Color.White;net.BackColor=Palette.Card;head.Controls.Add(title);head.Controls.Add(net);root.Controls.Add(head);
  var cards=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4};for(int i=0;i<4;i++)cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,25));AddCard(cards,"DOWNLOAD",down,0);AddCard(cards,"UPLOAD",up,1);AddCard(cards,"DAILY USAGE",daily,2);AddCard(cards,"MONTHLY USAGE",monthly,3);root.Controls.Add(cards);
  var mid=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};mid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,44));mid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,56));tops=Box("Top Applications (Today)");days=Box("Daily Usage (Last 7 Days)");mid.Controls.Add(tops);mid.Controls.Add(days);root.Controls.Add(mid);
  var active=new Panel{Dock=DockStyle.Fill,BackColor=Palette.Card,Padding=new Padding(14)};var bar=new Panel{Dock=DockStyle.Top,Height=42};var at=new Label{Text="Active Applications",Dock=DockStyle.Left,Width=220,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",11),TextAlign=ContentAlignment.MiddleLeft};FilterBox.Dock=DockStyle.Right;FilterBox.Width=170;FilterBox.DropDownStyle=ComboBoxStyle.DropDownList;FilterBox.Items.AddRange(new object[]{"All Connections","User Processes","System Processes","Limited / Blocked"});FilterBox.SelectedIndex=0;SearchBox.Dock=DockStyle.Right;SearchBox.Width=250;SearchBox.PlaceholderText="Search applications...";SearchBox.BackColor=Palette.Input;SearchBox.ForeColor=Color.White;bar.Controls.Add(FilterBox);bar.Controls.Add(SearchBox);bar.Controls.Add(at);active.Controls.Add(Grid);active.Controls.Add(bar);Grid.Dock=DockStyle.Fill;Grid.BringToFront();ConfigureGrid();root.Controls.Add(active);
  footer.Dock=DockStyle.Fill;footer.ForeColor=Palette.Muted;footer.TextAlign=ContentAlignment.MiddleLeft;root.Controls.Add(footer);
 }
 static FlowLayoutPanel Box(string title){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,BackColor=Palette.Card,Padding=new Padding(14),FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Margin=new Padding(4)};p.Controls.Add(new Label{Text=title,AutoSize=true,ForeColor=Color.White,Font=new Font("Segoe UI Semibold",11)});return p;}
 static void AddCard(TableLayoutPanel host,string name,Label value,int col){var p=new Panel{Dock=DockStyle.Fill,BackColor=Palette.Card,Margin=new Padding(4),Padding=new Padding(14)};var l=new Label{Text=name,Dock=DockStyle.Top,Height=24,ForeColor=Palette.Muted};value.Dock=DockStyle.Fill;value.ForeColor=Color.White;value.Font=new Font("Segoe UI",16,FontStyle.Bold);value.TextAlign=ContentAlignment.MiddleLeft;p.Controls.Add(value);p.Controls.Add(l);host.Controls.Add(p,col,0);}
 void ConfigureGrid(){Grid.BackgroundColor=Palette.Card;Grid.BorderStyle=BorderStyle.None;Grid.RowHeadersVisible=false;Grid.AllowUserToAddRows=false;Grid.AllowUserToDeleteRows=false;Grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;Grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.None;Grid.ColumnHeadersHeight=34;Grid.RowTemplate.Height=38;Grid.EnableHeadersVisualStyles=false;Grid.ColumnHeadersDefaultCellStyle=new DataGridViewCellStyle{BackColor=Palette.Input,ForeColor=Palette.Muted};Grid.DefaultCellStyle=new DataGridViewCellStyle{BackColor=Palette.Card,ForeColor=Color.White,SelectionBackColor=Color.FromArgb(22,53,86),SelectionForeColor=Color.White};
  Grid.Columns.Add(new DataGridViewImageColumn{Name="icon",HeaderText="",Width=34,ImageLayout=DataGridViewImageCellLayout.Zoom}); foreach(var x in new[]{("app","Application",190),("status","Status",80),("download","Download",90),("upload","Upload",90),("total","Total",85),("down","Limit Download",105),("up","Limit Upload",95),("rule","Rule",70),("action","Action",60),("pid","PID",90),("path","Path",160)}) Grid.Columns.Add(new DataGridViewTextBoxColumn{Name=x.Item1,HeaderText=x.Item2,Width=x.Item3}); Grid.Columns["app"]!.AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill;Grid.Columns["pid"]!.Visible=false;Grid.Columns["path"]!.Visible=false;Grid.CellDoubleClick+=(_,e)=>{if(e.RowIndex>=0)RowActionClicked?.Invoke(e.RowIndex,RowAction.Edit);};}
 public void SetSpeeds(double d,double u){down.Text=Gfx.Speed(d);up.Text=Gfx.Speed(u);}
 public void SetNetwork(string a,bool ok){net.Text=(ok?"● Connected":"● Disconnected")+"\n"+a;net.ForeColor=ok?Palette.Green:Color.IndianRed;}
 public void SetUsage(long rx,long tx,long month,double quota,IReadOnlyList<DayBars> d,IReadOnlyList<TopApp> t){daily.Text=Gfx.Bytes(rx+tx);monthly.Text=Gfx.Bytes(month);while(days.Controls.Count>1)days.Controls.RemoveAt(1);foreach(var x in d)days.Controls.Add(new Label{Text=$"{x.Day:ddd}   {Gfx.Bytes(x.Rx+x.Tx)}",AutoSize=true,ForeColor=Palette.Muted});while(tops.Controls.Count>1)tops.Controls.RemoveAt(1);if(t.Count==0)tops.Controls.Add(new Label{Text="No per-application traffic recorded today yet",AutoSize=true,ForeColor=Palette.Muted});else foreach(var x in t)tops.Controls.Add(new Label{Text=$"{x.Name}   {Gfx.Bytes(x.Bytes)}",AutoSize=true,ForeColor=Color.White});}
 public void SetFooter(string s)=>footer.Text=s;
}
